//! 🔤️ Actual JSON syntax custody keeps all twelve original variants and exact owned member names.
use semio_framework_job_failure::*;
use semio_framework_pack_json::JsonError;
use semio_framework_value::{ValueError,ValueRefusalKind,RetainedCloneGrant,RetainedCloneProgress,retirement::controlled::ControlledRetirement};
use OriginalDomainView as V;
fn fixture()->serde_json::Value{serde_json::from_str(include_str!("🧪️fixtures/🔣️.json")).unwrap()}
fn stock()->RetainedCloneGrant{RetainedCloneGrant{maximum_items:65536,maximum_copy_bytes:1048576,maximum_capacity_bytes:1048576,maximum_release_bytes:1048576,maximum_depth:4096}}
fn sample(kind:&str,name:&str,offset:usize)->JsonError{match kind{"Native"=>JsonError::Native(ValueError::new(ValueRefusalKind::InvalidValue,name.to_owned()).with_retained_progress(RetainedCloneProgress{copied_items:3,copied_bytes:7,..Default::default()})),"UnexpectedEof"=>JsonError::UnexpectedEof,"UnexpectedByte"=>JsonError::UnexpectedByte{found:255,offset},"InvalidNumber"=>JsonError::InvalidNumber(offset),"InvalidEscape"=>JsonError::InvalidEscape(offset),"InvalidUnicodeEscape"=>JsonError::InvalidUnicodeEscape(offset),"UnpairedSurrogate"=>JsonError::UnpairedSurrogate(offset),"ControlCharacterInString"=>JsonError::ControlCharacterInString{byte:17,offset},"InvalidUtf8"=>JsonError::InvalidUtf8,"TrailingData"=>JsonError::TrailingData(offset),"MaxDepthExceeded"=>JsonError::MaxDepthExceeded(129),"DuplicateMember"=>JsonError::DuplicateMember{name:name.to_owned(),offset},_=>panic!("unknown original JSON fixture")}}
fn json(p:&impl OriginalDomainProjection,path:&mut Vec<usize>)->serde_json::Value{match p.projection_view(path).unwrap(){V::IntrinsicNull=>serde_json::Value::Null,V::IntrinsicBool(v)=>v.into(),V::IntrinsicNumber(semio_framework_value::Number::UInt(v))=>v.into(),V::IntrinsicText(v)=>v.into(),V::IntrinsicObject(n)=>{let mut result=serde_json::Map::new();for index in 0..n{let key=p.projection_key(path,index).unwrap().to_owned();path.push(index);let value=json(p,path);path.pop();result.insert(key,value);}result.into()},_=>panic!("unexpected original JSON projection")}}
#[test]
fn complete_json_fields_borrow_the_original_and_match_third_party_json(){let law=fixture();let name=law["name"].as_str().unwrap();let offset=law["offset"].as_u64().unwrap()as usize;for row in law["variants"].as_array().unwrap(){let kind=row[0].as_str().unwrap();let original=sample(kind,name,offset);let pointer=match &original{JsonError::DuplicateMember{name,..}=>Some(name.as_ptr()),JsonError::Native(value)=>Some(value.message.as_ptr()),_=>None};let owner=OriginalJsonFailure::from(original);let(_,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||{assert_eq!(owner.projection_identity(),&owner.original as*const JsonError as usize);assert!(matches!(owner.projection_view(&[]).unwrap(),V::IntrinsicObject(n)if n==row.as_array().unwrap().len()-1));for(index,key)in row.as_array().unwrap()[1..].iter().enumerate(){assert_eq!(owner.projection_key(&[],index).unwrap(),key.as_str().unwrap());}assert!(matches!(owner.projection_view(&[0]).unwrap(),V::IntrinsicText(v)if v==kind));assert!(owner.projection_key(&[],row.as_array().unwrap().len()-1).is_err());if kind=="DuplicateMember"{assert!(matches!(owner.projection_view(&[1]).unwrap(),V::IntrinsicText(v)if Some(v.as_ptr())==pointer));}if kind=="Native"{assert!(matches!(owner.projection_view(&[1,1]).unwrap(),V::IntrinsicText(v)if Some(v.as_ptr())==pointer));assert_eq!(owner.domain_retained_progress().copied_items,3);assert_eq!(owner.domain_retained_progress().copied_bytes,7);}});assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));let wire=json(&owner,&mut Vec::new());assert_eq!(wire["kind"],kind);if let Some(actual)=wire.get("offset"){assert_eq!(*actual,serde_json::json!(offset))}if kind=="DuplicateMember"{assert_eq!(wire,serde_json::json!({"kind":kind,"name":name,"offset":offset}));}let encoded=serde_json::to_string(&wire).unwrap();assert_eq!(serde_json::from_str::<serde_json::Value>(&encoded).unwrap(),wire);let mut close=ControlledRetirement::retain(owner);for _ in 0..100000{if close.terminal_is_empty(){break}close.step(stock()).unwrap();}assert!(close.terminal_is_empty());}}
#[test]
fn original_json_source_custody_retains_denied_donor_and_refuses_foreign_source(){use semio_framework_job_testing_caller::OriginalJobFixtureCaller;use semio_framework_job_context::{OperationId,Generation};let grant=stock();let mut caller=OriginalJobFixtureCaller::admit(OperationId(9182),Generation(7),grant,||Some(1000),1500,65536);let mut foreign=OriginalJobFixtureCaller::admit(OperationId(9182),Generation(7),grant,||Some(1000),1500,65536);let mut owner=Some(OriginalJsonFailure::from(JsonError::DuplicateMember{name:String::from("duplicate 源"),offset:73}));let pointer=match &owner.as_ref().unwrap().original{JsonError::DuplicateMember{name,..}=>name.as_ptr(),_=>unreachable!()};let mut reservation=OriginalDomainReservation::new();caller.turn(grant,|cx|{assert!(reservation.prepare(cx)?);Ok(())}).unwrap();caller.turn(RetainedCloneGrant{maximum_copy_bytes:0,..grant},|cx|{assert!(!reservation.capture_original(cx,||owner.take().unwrap())?);Ok(())}).unwrap();assert!(owner.is_some());caller.turn(grant,|cx|{assert!(reservation.capture_original(cx,||owner.take().unwrap())?);Ok(())}).unwrap();assert!(owner.is_none());let allocation=reservation.allocation_identity();assert!(foreign.turn(grant,|cx|admit_original_domain_failure(&mut reservation,cx)).is_err());assert_eq!(reservation.allocation_identity(),allocation);let error=caller.turn(grant,|cx|admit_original_domain_failure(&mut reservation,cx)).unwrap().unwrap();let domain=error.primary_domain().unwrap();assert!(matches!(domain.projection().projection_view(&[1]).unwrap(),V::IntrinsicText(v)if v.as_ptr()==pointer));let mut close=ControlledRetirement::retain(error);for _ in 0..100000{if close.terminal_is_empty(){break}caller.turn(grant,|cx|{semio_framework_job::close_original_retained_step(cx,close.selected_demand(grant.maximum_copy_bytes)?,|grant|close.step(grant))?;Ok(())}).unwrap();}assert!(close.terminal_is_empty());caller.retire(grant);foreign.retire(grant);}
